using System;using System.Globalization;using System.Web.UI.WebControls;using ForteMove.Models.Operations;using ForteMove.Web.Infrastructure;namespace ForteMove.Web.Admin.Operations{public partial class Defects:AdminPage{protected void Page_Load(object s,EventArgs e){if(!IsPostBack){BindOptions();Bind();}}protected void btnApply_Click(object s,EventArgs e){Bind();}private void BindOptions(){ddlStatus.Items.Add(new ListItem("All statuses",string.Empty));foreach(DefectStatus x in Enum.GetValues(typeof(DefectStatus)))ddlStatus.Items.Add(new ListItem(x.ToString(),x.ToString()));ddlSeverity.Items.Add(new ListItem("All severities",string.Empty));foreach(DefectSeverity x in Enum.GetValues(typeof(DefectSeverity)))ddlSeverity.Items.Add(new ListItem(x.ToString(),x.ToString()));}private void Bind(){DefectStatus s;DefectSeverity v;var items=ServiceFactory.CreateOperationsAdminService().GetDefectReports(new DefectQuery{Status=Enum.TryParse(ddlStatus.SelectedValue,out s)?s:(DefectStatus?)null,Severity=Enum.TryParse(ddlSeverity.SelectedValue,out v)?v:(DefectSeverity?)null});rptItems.DataSource=items;rptItems.DataBind();pnlResults.Visible=items.Count>0;pnlEmpty.Visible=items.Count==0;}protected string FormatTime(object value){return ServiceFactory.CreateOperationsAdminService().ToOperationalTime(Convert.ToDateTime(value)).ToString("dd MMM yyyy HH:mm",CultureInfo.CurrentCulture);}protected string FormatCategory(object value){string x=Convert.ToString(value);return x=="EngineDrivetrain"?"Engine / drivetrain":x=="BodyInterior"?"Body / interior":x;}protected string SeverityClass(object value){return Convert.ToString(value)=="Critical"?"status-badge status-danger":Convert.ToString(value)=="Major"?"status-badge status-warning":"status-badge status-info";}}}
